-- SOMENTE LEITURA. Selecione explicitamente a conexão/esquema correto antes de executar.
-- A ferramenta não executa estas consultas. Nenhum dado de conta/personagem é solicitado.
SELECT DATABASE() AS effective_schema, VERSION() AS database_version;
SELECT table_name FROM information_schema.tables WHERE table_schema = DATABASE() AND table_name IN ('accounts', 'build_orders', 'campaign_active', 'campaign_progress', 'campaign_run_nodes', 'campaign_runs', 'character_buildings', 'character_castles', 'character_currencies', 'character_farms', 'character_gold_accrual', 'character_item_buffs', 'character_items', 'character_skill_state', 'characters', 'currency_ledger', 'farm_logs', 'friend_groups', 'friend_relations', 'item_template', 'login_sessions', 'tutorial_battle_rewards', 'vip_progress') ORDER BY table_name;
SELECT table_name, column_name, column_type, is_nullable FROM information_schema.columns WHERE table_schema = DATABASE() AND table_name IN ('accounts', 'build_orders', 'campaign_active', 'campaign_progress', 'campaign_run_nodes', 'campaign_runs', 'character_buildings', 'character_castles', 'character_currencies', 'character_farms', 'character_gold_accrual', 'character_item_buffs', 'character_items', 'character_skill_state', 'characters', 'currency_ledger', 'farm_logs', 'friend_groups', 'friend_relations', 'item_template', 'login_sessions', 'tutorial_battle_rewards', 'vip_progress') ORDER BY table_name, ordinal_position;
-- Execute a próxima consulta apenas se flyway_schema_history existir no esquema efetivo:
SELECT installed_rank, version, description, type, script, checksum, success FROM flyway_schema_history ORDER BY installed_rank;
